const now = Date.now();
export const posMenuFinishedStocks: FinishedStock[] = retailBranchIds.flatMap((branchId, branchIndex) => posMenuProducts.filter(product => product.active).map((product, productIndex) => ({
  id: `menu-stock-${branchId}-${product.id}`,
  productId: product.id,
  branchId,
  qty: 18 + ((productIndex * 7 + branchIndex * 11) % 74),
  batchNo: `NS-${String(productIndex + 1).padStart(4, '0')}-25`,
  producedAt: new Date(now - 8 * 60 * 60 * 1000).toISOString(),
  expiryAt: new Date(now + product.shelfLifeHours * 60 * 60 * 1000).toISOString(),
  costPerUnit: Math.round(product.price * 0.58),
})));

